parameters.query:
SELECT
  (SELECT row_to_json(p) FROM credscore.parametros_pesos p WHERE ativo = true LIMIT 1) AS pesos,
  (SELECT row_to_json(t) FROM credscore.parametros_thresholds t WHERE ativo = true LIMIT 1) AS thresholds;

parameters.jsCode:
const input = $('When Executed by Another Workflow').item.json;
const dados = $('Buscar Pesos e Thresholds Ativos').item.json;
const pesos = dados.pesos || {};
const thr = dados.thresholds || {};

const s1 = Number(input.s1_fiscal ?? 0);
const s2 = Number(input.s2_financeira ?? 0);
const s3 = Number(input.s3_regime ?? 0);
const s4 = Number(input.s4_dependencia ?? 0);
const s5 = input.s5_maturidade === null || input.s5_maturidade === undefined ? null : Number(input.s5_maturidade);
const completude = Number(input.completude_pct ?? 100);

const temD5 = s5 !== null;

let w = { d1: Number(pesos.w_d1), d2: Number(pesos.w_d2), d3: Number(pesos.w_d3), d4: Number(pesos.w_d4), d5: Number(pesos.w_d5) };
if (!temD5) {
  const fator = 1 / (1 - w.d5);
  w = { d1: w.d1 * fator, d2: w.d2 * fator, d3: w.d3 * fator, d4: w.d4 * fator, d5: 0 };
}

const scoreTotal = Math.round((w.d1*s1 + w.d2*s2 + w.d3*s3 + w.d4*s4 + w.d5*(s5 ?? 0)) * 100) / 100;

let decisao = null;
let status = 'concluido';

if (completude < Number(thr.completude_minima_pct)) {
  status = 'analise_manual';
  decisao = null;
} else {
  if (scoreTotal >= Number(thr.elegivel_min)) decisao = 'elegivel';
  else if (scoreTotal >= Number(thr.condicionado_min)) decisao = 'elegivel_condicionado';
  else if (scoreTotal >= Number(thr.atencao_min)) decisao = 'atencao';
  else decisao = 'nao_elegivel';
}

return [{ json: {
  score_total: scoreTotal,
  decisao,
  status,
  preliminar: !temD5,
  pesos_usados: { w_d1: w.d1, w_d2: w.d2, w_d3: w.d3, w_d4: w.d4, w_d5: w.d5 },
  versao_pesos_id: pesos.id,
  versao_thresholds_id: thr.id
} }];

